<section class="section"><header class="admin-header"><div><h1>Administrar productos</h1><p>Gestiona el catálogo, contenido público y beneficios.</p></div><a href="products.php?action=new" class="btn">Nuevo producto</a></header><?php if (!empty($error)): ?><p class="alert alert--error"><?php echo htmlspecialchars($error, ENT_QUOTES, 'UTF-8'); ?></p><?php endif; ?><?php if (!$products): ?><div class="card empty-state"><p>No hay productos registrados.</p></div><?php else: ?><div class="table-wrapper"><table class="table"><thead><tr><th>ID</th><th>Imagen</th><th>Nombre</th><th>Descripción corta</th><th>Acciones</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><?php echo (int) $product->id; ?></td><td><?php if ($product->imagePath): ?><img src="../<?php echo htmlspecialchars($product->imagePath, ENT_QUOTES, 'UTF-8'); ?>" alt="" width="50" height="50" style="object-fit:cover;border-radius:4px;"><?php else: ?><span class="ticket-muted">Sin imagen</span><?php endif; ?></td><td><strong><?php echo htmlspecialchars($product->name, ENT_QUOTES, 'UTF-8'); ?></strong></td><td><?php echo htmlspecialchars($product->shortDescription, ENT_QUOTES, 'UTF-8'); ?></td><td class="table__actions"><a href="products.php?action=edit&amp;id=<?php echo $product->id; ?>" class="table__action" aria-label="Editar producto" title="Editar producto"><i class="fas fa-edit" aria-hidden="true"></i></a><form method="post" class="inline-form" onsubmit="return confirm('¿Seguro que deseas eliminar este producto?');"><input type="hidden" name="_csrf_token" value="<?php echo $csrf; ?>"><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?php echo $product->id; ?>"><button type="submit" class="table__action table__action--danger table__action-button" aria-label="Eliminar producto" title="Eliminar producto"><i class="fas fa-trash" aria-hidden="true"></i></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
